def verifier(assign):
    # Validate presence of slots
    if not all(k in assign for k in ('width', 'row_target', 'col_target')):
        # Missing keys
        return (False, None)
    width = assign['width']
    row_target = assign['row_target']
    col_target = assign['col_target']
    # Basic domain checks
    if not isinstance(width, int) or not isinstance(row_target, int) or not isinstance(col_target, int):
        # Non-integer parameters
        return (False, None)
    if width < 4 or width > 6:
        # Enforce difficulty via width
        return (False, None)
    if row_target < 0 or col_target < 0:
        return (False, None)
    if col_target > 99*width:
        # Sum of width two-digit numbers cannot exceed 99*width
        return (False, None)
    # Extract row-target digits padded to width
    s = [0]*width
    rt = row_target
    for i in range(width-1, -1, -1):
        s[i] = rt % 10
        rt //= 10
    # DP counting across carry patterns
    total = 0
    any_nonzero_c = False
    # Enumerate c_2..c_w via bitmask; c_1=0 and c_{w+1}=0
    for mask in range(1 << (width-1)):
        c = [0]*(width+2)
        c[1] = 0
        for i in range(2, width+1):
            bitpos = width - i
            c[i] = (mask >> bitpos) & 1
        c[width+1] = 0
        # Compute T_i = a_i + b_i for each column
        T = []
        ok = True
        for i in range(1, width+1):
            Ti = s[i-1] - c[i+1] + 10*c[i]
            if Ti < 0 or Ti > 18:
                ok = False
                break
            T.append(Ti)
        if not ok:
            continue
        S_T = sum(T)
        diff = col_target - S_T
        if diff % 9 != 0:
            continue
        A_sum = diff // 9
        if A_sum < 0 or A_sum > 9*width:
            continue
        # Bounds for each a_i
        L = []
        U = []
        sumL = 0
        sumU = 0
        for Ti in T:
            Li = 0 if Ti <= 9 else Ti - 9
            Ui = Ti if Ti <= 9 else 9
            L.append(Li)
            U.append(Ui)
            sumL += Li
            sumU += Ui
        if A_sum < sumL or A_sum > sumU:
            continue
        # DP
        dp = [0]*(A_sum+1)
        dp[0] = 1
        for i in range(width):
            new = [0]*(A_sum+1)
            Li, Ui = L[i], U[i]
            for cur in range(A_sum+1):
                cnt = dp[cur]
                if cnt == 0:
                    continue
                for val in range(Li, Ui+1):
                    nxt = cur + val
                    if nxt <= A_sum:
                        new[nxt] += cnt
            dp = new
        ways = dp[A_sum]
        if ways > 0 and any(c[i] == 1 for i in range(1, width+1)):
            any_nonzero_c = True
        total += ways
    # Enforce difficulty: ensure at least a certain number of solutions and that nonzero carry patterns contribute
    min_count = 60
    if total < min_count:
        # Too few solutions; not sufficiently challenging
        return (False, None)
    if not any_nonzero_c:
        # No carry patterns contribute; problem reduces to trivial bounded composition
        return (False, None)
    return (True, total)
